{
  "technical_and_design_decisions": [
    "Upgrade Spring XD core and module POM dependencies to Spring Boot 1.2.0.RELEASE and align all transitivity requirements (Spring Framework 4.1.3.RELEASE, Jackson 2.4.4, Jetty 9.2.4, etc.).",
    "Extend HDFS Dataset Sink configuration properties to allow selecting or disabling Avro compression codecs (e.g., NONE, SNAPPY, DEFLATE) via configuration metadata.",
    "Expose JavaMail custom properties in the Mail sink spring-integration adapter configuration to enable TLS/SSL properties passed via a property bean reference.",
    "Implement YML manifest file loading and parsing into deployment properties for Spring XD stream deployments alongside inline deployment properties.",
    "Implement generic compression/decompression transformers for gzip and zip payloads, and expose these options natively in RabbitMQ source and sink module configurations."
  ],
  "assumptions": [
    "Development and testing environment includes standard Spring XD sandbox cluster setup with access to Hadoop/HDFS, RabbitMQ, and test mail server instances.",
    "A single full-stack Java developer will perform all architecture, code modification, benchmarking, test creation, and verification tasks.",
    "All dependencies specified in U5 are mutually compatible under Spring Boot 1.2.0.RELEASE without major architectural rewrites.",
    "Benchmarking for U1 requires standard dataset generators and comparison scripts on standard XD batch runner environments."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Requirements Analysis & Technical Design",
      "activity_description": "Analyze user stories U1-U8, map impacted Spring XD components/modules, define configuration properties, and plan the dependency migration strategy.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Sqoop vs jdbchdfs Batch Job Benchmarking (U1)",
      "activity_description": "Setup test dataset, create and execute comparative benchmark scripts for Sqoop and jdbchdfs batch jobs, capture performance statistics, and document results.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Avro Codec Configuration in HDFS Dataset Sink (U2)",
      "activity_description": "Modify HDFS Dataset sink module to expose compression codec settings, allow disabling Snappy, support custom Avro codecs, and add unit/integration tests.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Mail Sink Secure TLS/SSL Configuration (U3)",
      "activity_description": "Update Mail sink XML/Java config definitions to accept and pass javaMailProperties bean for TLS/SSL IMAP/SMTP configurations, including test verification.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Expose partitionResultsTimeout Metadata (U4)",
      "activity_description": "Update metadata definitions and configuration files for OOTB jobs inheriting singlestep-partitioning strategy to expose partitionResultsTimeout, and update documentation.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Spring Boot 1.2.0 Dependency Upgrade (U5)",
      "activity_description": "Update project build scripts to Spring Boot 1.2.0.RELEASE and all listed library versions; resolve API breaking changes, dependency conflicts, and unit test failures.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Deployment Manifest YML File Support (U6)",
      "activity_description": "Develop parser support for external YML deployment manifest files in XD stream deployment definition pipeline, with unit and integration testing.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Generic Payload Compression & Decompression Support (U7)",
      "activity_description": "Implement gzip and zip compression/decompression transformers and integration helpers for payload processing.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "RabbitMQ Source and Sink Compression Integration (U8)",
      "activity_description": "Integrate compression and decompression configurations directly into RabbitMQ source and sink modules, updated converters, and verify end-to-end messaging.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "End-to-End Integration Testing & Release Preparation",
      "activity_description": "Execute full test suites across updated XD modules, verify cluster execution with updated Spring Boot runtime, fix residual bugs, and assemble final delivery.",
      "most_likely_effort": 3.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 22.5
  }
}
